      "name": "Munição Divina (Maior)",
      "description": "Embutido nesta peça de munição está uma lasca brilhante de um warshard. Quando uma munição dilacerante ativada atinge um alvo, o corpo da criatura atingida tenta se despedaçar, causando uma dor nauseante. Em vez do dano normal, a munição causa 15d8 de dano cortante. O alvo pode tentar um teste de resistência (fortitude, dc:38); é necessária uma penalidade de -2 de circunstância para este teste se o Golpe for um acerto crítico.\nSucesso Crítico O inimigo sofre o dano normal da munição, em vez dos 15d8 de dano cortante.\nSucesso O inimigo sofre metade do dano.\nFalha O inimigo sofre dano total e fica Enjoado 1.\nFalha Crítica O inimigo sofre o dobro de dano e fica Enjoado 2. Uma criatura com PV reduzido a 0 devido a esse dano é dilacerada membro por membro e morre instantaneamente; seu equipamento permanece.",
