      "name": "Soro Carmesim de Sangue Divino (Maior)",
      "description": "Ativar 1 (manipular)\nEmbora contenha apenas uma pequena gota do sangue de Gorum, beber esta poção espessa e rodopiante enche o usuário de ira e resiliência divinas. Enquanto estiver sob o efeito da poção, você ganha +4 de bônus de status nas jogadas de dano físico por 1 minuto.\nEfeito: Soro Sangue Divino Carmesim\nNa primeira vez durante esse minuto você é reduzido a 0 Pontos de Vida, mas não morre imediatamente, você evita ser nocauteado, recupera 6d8+20 Pontos de Vida de cura e fica Confuso por 1 rodada, e sua condição de Ferido aumenta em 1.",
