      "name": "Chifre de Demônio Polido (Maior)",
      "description": "Este coração mágico é feito da ponta de um chifre de demônio que foi polido até ficar liso e brilhante. A CD de qualquer magia lançado ao ativar este item é 29.\n• Armadura Você ganha resistência 10 a profano.\n• Arma Depois de lançar uma magia de encantamento ativando o chifre, seus ataques com a arma causam 1d8 de dano mental adicional até o final do seu próximo turno.\nEfeito: Chifre de Demônio Polido - Armadura\nEfeito: Chifre de Demônio Polido - Arma\nAtivar lançar uma magia\nEfeito Você conjura Daze (teste (vontade, dc:29, básico, traços:mental,emoção,medo, opções:magia)).\nAtivar lançar uma magia\nFrequência uma vez por dia\nEfeito Você conjura Medo do 3º Rank (teste (vontade, dc:29, básico, características: truque, magia, mental, não letal)).\nAtivar lançar uma magia\nFrequência uma vez por dia\nEfeito Você lança Maldição do Pária (teste (vontade, dc:29, características: infortúnio, maldição, mental, magia)).\nAtivar lançar uma magia\nFrequência uma vez por dia\nEfeito Você conjura Visão da Morte (teste (vontade, dc:29, características: emoção, morte, medo, mental, magia)).",
