      "name": "Manto dos Espinhos Devoradores",
      "description": "Este manto parece ser tecido com mil folhas vivas, faminto por carne e ansioso para defender quem o usa.\nAtivar—Bite Back r (concentrado)\nFrequência uma vez por rodada\nGatilho Você sofre dano por um ataque corpo a corpo de uma criatura adjacente\nEfeito As folhas atacam seu atacante, erguendo-se para revelar mandíbulas cortantes feitas de espinhos malignos. A criatura desencadeadora deve tentar um teste de resistência (reflexo, dc:30, opções:efeito de dano).\nSucesso A criatura não é afetada.\nFalha A criatura sofre 2d6 de dano perfurante.\nFalha Crítica A criatura sofre 4d6 de dano perfurante] de dano.",
