      "description": "Este musgo cor de vinho cresce em tufos em forma de coração e libera um aroma agradável e calmante. A CD de qualquer magia lançado ao ativar este item é 24.\n• Armadura Você ganha resistência 5 a dano mental e +1 de bônus de item em testes de resistência contra efeitos com o traço emoção.\n• Arma Depois de lançar uma magia de cura ativando o heartmoss, a arma exala um aroma calmante. Seus ataques com a arma afixada possuem o traço não letal por 1 minuto. Até o final do seu próximo turno, Golpes com a arma afixada fazem com que o alvo fique Estupefato 2 por 1 rodada se acertar (ou por 3 rodadas em caso de acerto crítico).\nAtivar lançar uma magia\nEfeito Você lança Estabilizar.\nAtivar lançar uma magia\nFrequência uma vez por dia\nEfeito Você lança Cura do 3º Rank.",
