      "name": "Frasco de inflamação (moderado)",
      "description": "Ative um ataque\nEste frasco contém um irritante cáustico que torna a pele, escamas ou carapaça do alvo extremamente sensíveis a novos cortes e queimaduras. Um frasco de inflamação causa 2d6 de dano de ácido e 2 de dano de respingo de ácido. Ao acertar, o alvo também ganha fraqueza 2 a ácido, fogo e dano cortante por 3 rodadas. Você ganha +1 de bônus de item nas jogadas de ataque.\nO alvo pode encerrar o efeito de fraqueza de três maneiras: sendo encharcado de água (como submersão ou exposição a um efeito de água em área), recebendo Primeiros Socorros Administrados (CD 20) ou recuperando Pontos de Vida de um único efeito igual ao dobro do nível do frasco de inflamação. Uma criatura que falhar criticamente em Administrar Primeiros Socorros desta forma causa dano não tipificado ao alvo igual ao dano ácido inicial do frasco de inflamação.\nEfeito: Frasco de Inflamação",
