      "description": "Ative um ataque\nA minúscula aranha-armadilha da Floresta Verduran põe seus ovos em uma teia piramidal, e seus filhotes eclodem apenas em resposta a vibrações intensas, como as lutas de um inseto capturado ou mesmo de um pássaro canoro. Alquimistas sádicos coletam e aumentam esses ovos, empacotando-os em bolsas de seda que expelem milhares de bebês-aranhas que picam com o impacto.\nAté serem eliminadas – ou para o alvo desesperado, incineradas – essas aranhas tornam difícil se concentrar em qualquer outra coisa que não seja escapar do enxame. O efeito de fascinação termina automaticamente se uma criatura usar outras ações hostis contra o alvo, mas as ações hostis contra os aliados do alvo não encerram automaticamente o efeito.\nVocê ganha +1 de bônus de item nas jogadas de ataque. A bomba causa 2d6 de dano persistente de veneno, 2 de dano de veneno e fascina o alvo enquanto durar o dano persistente.",
