      "description": "A Trégua do Dilúvio é uma época de relativa paz, e esta tatuagem de um rio pode acalmar seu temperamento quando você poderia atacar. Você ganha +1 de bônus de item em testes de Diplomacia feitos contra orcs que honram a Trégua do Dilúvio.\nAtivar – Incorporar a Trégua (concentrar)\nFrequência uma vez por dia\nGatilho Um efeito mental obrigaria você a ferir um aliado ou espectador\nEfeito Tente um teste de neutralização com um Rank de neutralização de 6 para encerrar o efeito.",
