      "name": "Lâmina Bebedora de Sangue",
      "description": "Esta espada curta impressionante +1 tem o desenho de uma boca com presas esculpida no cabo. Sempre que a lâmina extrai sangue, ela brilha com uma energia vermelha opaca, como se fosse fortalecida pelo sabor do sangue.\nAtivar—Beba Life 2 (concentração)\nFrequência uma vez por dia\nEfeito A lâmina bebedora de sangue guia sua mão para cortar um inimigo e alimenta você com seu sangue. Faça um golpe com a lâmina. Se acertar, o ataque causa 1d8 de dano de sangramento persistente adicional. Você também ganha 1d8 Pontos de Vida temporários por 1 minuto.\nEfeito: Lâmina Bebedora de Sangue",
